        function initAtelierVideoShowcase() {
            const mainVideo = document.getElementById('featured-atelier-video');
            const mainFrame = document.getElementById('main-video-frame');
            if (!mainVideo || !mainFrame) return;

            const badgeCat = document.getElementById('featured-badge-cat');
            const counterPill = document.getElementById('featured-counter-pill');
            const tagPill = document.getElementById('featured-tag-pill');
            const titleEl = document.getElementById('featured-video-title');
            const descEl = document.getElementById('featured-video-desc');
            const specFabric = document.getElementById('featured-spec-fabric');
            const specFinish = document.getElementById('featured-spec-finish');
            const specAvail = document.getElementById('featured-spec-avail');

            const btnPlay = document.getElementById('btn-video-play');
            const iconPlay = document.getElementById('icon-video-play');
            const centerPlay = document.getElementById('featured-center-play');
            const centerIcon = document.getElementById('featured-center-icon');
            const btnMute = document.getElementById('btn-video-mute');
            const iconMute = document.getElementById('icon-video-mute');
            const labelMute = document.getElementById('label-video-mute');
            const btnFullscreen = document.getElementById('btn-video-fullscreen');
            const progressTrack = document.getElementById('featured-progress-track');
            const progressBar = document.getElementById('featured-progress-bar');
            const timeDisplay = document.getElementById('featured-time-display');
            const btnOrderLook = document.getElementById('btn-order-video-look');
            const btnPrev = document.getElementById('btn-prev-reel');
            const btnNext = document.getElementById('btn-next-reel');

            const reelCards = Array.from(document.querySelectorAll('.video-reel-card'));
            const pillBtns = Array.from(document.querySelectorAll('.video-pill-btn'));

            let currentIndex = 0;

            function formatTime(sec) {
                if (!sec || isNaN(sec)) return "0:00";
                const m = Math.floor(sec / 60);
                const s = Math.floor(sec % 60);
                return `${m}:${s < 10 ? '0' : ''}${s}`;
            }

            function syncPlayUI() {
                const playing = !mainVideo.paused && !mainVideo.ended;
                mainFrame.classList.toggle('is-playing', playing);
                if (iconPlay) iconPlay.className = playing ? 'fa-solid fa-pause text-xs' : 'fa-solid fa-play text-xs';
                if (centerIcon) centerIcon.className = playing ? 'fa-solid fa-pause text-xl' : 'fa-solid fa-play text-xl';
            }

            function syncMuteUI() {
                const muted = mainVideo.muted;
                if (iconMute) iconMute.className = muted ? 'fa-solid fa-volume-xmark' : 'fa-solid fa-volume-high text-emeraldBrand-bright';
                if (labelMute) labelMute.textContent = muted ? 'Activer le son' : 'Son activé';
            }

            function selectReel(index, autoPlay = true) {
                currentIndex = (index + ATELIER_VIDEOS.length) % ATELIER_VIDEOS.length;
                const info = ATELIER_VIDEOS[currentIndex];
                const targetCard = reelCards[currentIndex];
                if (!targetCard) return;

                const thumbVid = targetCard.querySelector('video');
                const newSrc = thumbVid ? thumbVid.getAttribute('src') : '';
                const newPoster = thumbVid ? thumbVid.getAttribute('poster') : '';

                mainFrame.classList.remove('video-fade-swap');
                void mainFrame.offsetWidth;
                mainFrame.classList.add('video-fade-swap');

                if (newPoster) mainVideo.setAttribute('poster', newPoster);
                if (newSrc && mainVideo.getAttribute('src') !== newSrc) {
                    mainVideo.setAttribute('src', newSrc);
                    mainVideo.load();
                }

                badgeCat.textContent = info.badge;
                counterPill.textContent = info.counter;
                tagPill.textContent = info.tag;
                titleEl.textContent = info.title;
                descEl.textContent = info.desc;
                specFabric.textContent = info.fabric;
                specFinish.textContent = info.finish;
                specAvail.textContent = info.avail;

                // Update active state on cards
                reelCards.forEach((card, idx) => {
                    const isActive = idx === currentIndex;
                    card.classList.toggle('active-reel', isActive);
                    const badgeIcon = card.querySelector('.reel-status-badge i');
                    if (badgeIcon) {
                        badgeIcon.className = isActive ? 'fa-solid fa-volume-high text-emeraldBrand' : 'fa-solid fa-play';
                    }
                });

                // Update active state on top pills
                pillBtns.forEach((btn, idx) => {
                    const isActive = idx === currentIndex;
                    btn.className = isActive
                        ? 'video-pill-btn bg-navy text-white border border-navy px-4 py-2.5 rounded-full text-xs font-bold uppercase tracking-wider transition-all shadow-sm flex items-center gap-2'
                        : 'video-pill-btn bg-white text-navy border border-slate-300 hover:border-emeraldBrand px-4 py-2.5 rounded-full text-xs font-bold uppercase tracking-wider transition-all flex items-center gap-2';
                });

                if (autoPlay) {
                    mainVideo.play().then(syncPlayUI).catch(() => syncPlayUI());
                } else {
                    syncPlayUI();
                }
            }

            function togglePlay() {
                if (mainVideo.paused) {
                    mainVideo.play().then(syncPlayUI).catch(() => {});
                } else {
                    mainVideo.pause();
                    syncPlayUI();
                }
            }

            btnPlay.addEventListener('click', togglePlay);
            centerPlay.addEventListener('click', togglePlay);
            mainVideo.addEventListener('click', togglePlay);

            btnMute.addEventListener('click', () => {
                mainVideo.muted = !mainVideo.muted;
                syncMuteUI();
            });

            btnFullscreen.addEventListener('click', () => {
                if (mainVideo.requestFullscreen) {
                    mainVideo.requestFullscreen();
                } else if (mainVideo.webkitEnterFullscreen) {
                    mainVideo.webkitEnterFullscreen();
                }
            });

            mainVideo.addEventListener('timeupdate', () => {
                if (mainVideo.duration) {
                    const pct = (mainVideo.currentTime / mainVideo.duration) * 100;
                    progressBar.style.width = `${pct}%`;
                    timeDisplay.textContent = `${formatTime(mainVideo.currentTime)} / ${formatTime(mainVideo.duration)}`;
                }
            });

            mainVideo.addEventListener('play', syncPlayUI);
            mainVideo.addEventListener('pause', syncPlayUI);

            progressTrack.addEventListener('click', (e) => {
                if (!mainVideo.duration) return;
                const rect = progressTrack.getBoundingClientRect();
                const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
                mainVideo.currentTime = ratio * mainVideo.duration;
            });

            btnPrev.addEventListener('click', () => selectReel(currentIndex - 1, true));
            btnNext.addEventListener('click', () => selectReel(currentIndex + 1, true));

            reelCards.forEach((card, idx) => {
                const thumbVideo = card.querySelector('video');
                card.addEventListener('click', () => selectReel(idx, true));
                card.addEventListener('mouseenter', () => {
                    if (thumbVideo) thumbVideo.play().catch(() => {});
                });
                card.addEventListener('mouseleave', () => {
                    if (thumbVideo) {
                        thumbVideo.pause();
                        thumbVideo.currentTime = 0;
                    }
                });
            });

            pillBtns.forEach((btn) => {
                btn.addEventListener('click', () => {
                    const idx = parseInt(btn.getAttribute('data-reel-select'), 10);
                    selectReel(idx, true);
                });
            });

            btnOrderLook.addEventListener('click', () => {
                const info = ATELIER_VIDEOS[currentIndex];
                if (typeof window.orderFromLookbook === 'function') {
                    window.orderFromLookbook(info.title, info.garmentType);
                } else {
                    const surMesure = document.getElementById('sur-mesure');
                    if (surMesure) surMesure.scrollIntoView({ behavior: 'smooth' });
                }
            });

            // Auto-play / pause intelligent selon la visibilité à l'écran
            if ('IntersectionObserver' in window) {
                const videoObserver = new IntersectionObserver((entries) => {
                    entries.forEach((entry) => {
                        if (entry.isIntersecting) {
                            mainVideo.play().then(syncPlayUI).catch(() => {});
                        } else {
                            mainVideo.pause();
                            syncPlayUI();
                        }
                    });
                }, { threshold: 0.25 });
                videoObserver.observe(mainFrame);
            }
        }
